# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">COOKING METHODS (PİŞİRME YÖNTEMLERİ)</text>\n  <rect x="25" y="55" width="205" height="90" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="127" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">BAKE &amp; ROAST (In the oven)</text>\n  <text x="127" y="103" text-anchor="middle" font-size="11" fill="#334155">• Bake: cake, bread, cookies, pie</text>\n  <text x="127" y="123" text-anchor="middle" font-size="11" fill="#334155">• Roast: chicken, meat, beef</text>\n  <rect x="247" y="55" width="205" height="90" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">BOIL &amp; STEAM (With water)</text>\n  <text x="350" y="103" text-anchor="middle" font-size="11" fill="#334155">• Boil: pasta, eggs, potatoes (haşlamak)</text>\n  <text x="350" y="123" text-anchor="middle" font-size="11" fill="#334155">• Steam: broccoli, carrots (buharda)</text>\n  <rect x="470" y="55" width="205" height="90" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="572" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">FRY &amp; GRILL (Heat / Oil)</text>\n  <text x="572" y="103" text-anchor="middle" font-size="11" fill="#334155">• Fry: chips, omelette in hot oil</text>\n  <text x="572" y="123" text-anchor="middle" font-size="11" fill="#334155">• Grill: fish, steak on barbecue</text>\n  <rect x="25" y="158" width="650" height="82" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="350" y="182" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">VERBS &amp; KITCHEN TOOLS MATCHING (FİİL - ARAÇ EŞLEŞTİRMESİ)</text>\n  <text x="350" y="205" text-anchor="middle" font-size="11.5" fill="#334155">peel → peeler / knife  |  grate → grater  |  drain / strain → strainer  |  mash → masher / fork</text>\n  <text x="350" y="225" text-anchor="middle" font-size="11.5" fill="#334155">chop / slice / dice → knife &amp; cutting board  |  roll → rolling pin  |  whisk → whisk  |  bake → oven</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DESCRIBING A PROCESS: SEQUENCE LINKERS (SIRALAMA BAĞLAÇLARI)</text>\n  <rect x="30" y="60" width="145" height="170" rx="8" fill="#dcfce7" stroke="#22c55e"/>\n  <text x="102" y="88" text-anchor="middle" font-size="14" font-weight="bold" fill="#15803d">1. FIRST</text>\n  <text x="102" y="112" text-anchor="middle" font-size="11" fill="#334155">(İlk olarak)</text>\n  <text x="102" y="142" text-anchor="middle" font-size="11" fill="#475569">"First, put some oil</text>\n  <text x="102" y="160" text-anchor="middle" font-size="11" fill="#475569">into a pan and</text>\n  <text x="102" y="178" text-anchor="middle" font-size="11" fill="#475569">heat it."</text>\n  <text x="102" y="210" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">Daima 1. Cümle!</text>\n  <rect x="190" y="60" width="145" height="170" rx="8" fill="#dbeafe" stroke="#3b82f6"/>\n  <text x="262" y="88" text-anchor="middle" font-size="14" font-weight="bold" fill="#1d4ed8">2. SECOND</text>\n  <text x="262" y="112" text-anchor="middle" font-size="11" fill="#334155">(İkinci olarak)</text>\n  <text x="262" y="142" text-anchor="middle" font-size="11" fill="#475569">"Second, crack and</text>\n  <text x="262" y="160" text-anchor="middle" font-size="11" fill="#475569">mix two eggs in</text>\n  <text x="262" y="178" text-anchor="middle" font-size="11" fill="#475569">a bowl."</text>\n  <text x="262" y="210" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e40af">2. Aşama!</text>\n  <rect x="350" y="60" width="160" height="170" rx="8" fill="#fef9c3" stroke="#eab308"/>\n  <text x="430" y="85" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">3-4. NEXT / THEN /</text>\n  <text x="430" y="103" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">AFTER THAT</text>\n  <text x="430" y="135" text-anchor="middle" font-size="11" fill="#475569">"Then, add some salt.</text>\n  <text x="430" y="155" text-anchor="middle" font-size="11" fill="#475569">After that, add cheese</text>\n  <text x="430" y="175" text-anchor="middle" font-size="11" fill="#475569">and milk."</text>\n  <text x="430" y="210" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#854d0e">Ara Basamaklar!</text>\n  <rect x="525" y="60" width="145" height="170" rx="8" fill="#fce7f3" stroke="#ec4899"/>\n  <text x="597" y="88" text-anchor="middle" font-size="14" font-weight="bold" fill="#be185d">5. FINALLY</text>\n  <text x="597" y="112" text-anchor="middle" font-size="11" fill="#334155">(Son olarak)</text>\n  <text x="597" y="142" text-anchor="middle" font-size="11" fill="#475569">"Finally, pour the</text>\n  <text x="597" y="160" text-anchor="middle" font-size="11" fill="#475569">mixture into the pan</text>\n  <text x="597" y="178" text-anchor="middle" font-size="11" fill="#475569">and serve hot."</text>\n  <text x="597" y="210" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#9d174d">Daima Son Cümle!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TASTES, PREFERENCES &amp; KITCHEN INQUIRIES</text>\n  <rect x="35" y="55" width="305" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="187" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Taste Adjectives (Tat Sıfatları)</text>\n  <text x="55" y="108" font-size="11.5" fill="#334155">• Sweet (Tatlı): baklava, honey, chocolate</text>\n  <text x="55" y="132" font-size="11.5" fill="#334155">• Sour (Ekşi): lemon, green plum, vinegar</text>\n  <text x="55" y="156" font-size="11.5" fill="#334155">• Spicy (Baharatlı / Acı): chili pepper, taco</text>\n  <text x="55" y="180" font-size="11.5" fill="#334155">• Salty (Tuzlu) / Greasy, Fatty (Yağlı)</text>\n  <text x="55" y="204" font-size="11.5" fill="#334155">• Bitter (Acı - kahve) / Milky (Sütlü)</text>\n  <rect x="360" y="55" width="305" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="512" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Preferences &amp; Simple Inquiries</text>\n  <text x="380" y="108" font-size="11.5" font-weight="bold" fill="#166534">• Expressing Preferences:</text>\n  <text x="385" y="128" font-size="11" fill="#334155">"I prefer grilling fish to frying it."</text>\n  <text x="385" y="146" font-size="11" fill="#334155">"I love eating homemade pizza."</text>\n  <text x="380" y="174" font-size="11.5" font-weight="bold" fill="#166534">• Making Simple Inquiries:</text>\n  <text x="385" y="194" font-size="11" fill="#334155">- What are the ingredients? (Malzemeler neler?)</text>\n  <text x="385" y="214" font-size="11" fill="#334155">- How long do we bake it? (Ne kadar süre pişiririz?)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
